from pathlib import Path
import sys
root=Path(__file__).parent
service=(root/'src/medical-records/medical-records.service.ts').read_text()
controller=(root/'src/medical-records/medical-records.controller.ts').read_text()
screen=(root/'mobile/src/screens/PatientHealthFileScreen.tsx').read_text()
api=(root/'mobile/src/api/client.ts').read_text()
uploads=(root/'src/uploads/uploads.service.ts').read_text()
checks=[]
def check(name,ok): checks.append((name,bool(ok)))
check('share list remains patient-only',"if (actor.role !== UserRole.PATIENT) throw new ForbiddenException('قائمة الموافقات متاحة للمريض فقط')" in service)
check('share list is scoped to authenticated patient',"where: { patientUserId: actor.sub }" in service)
check('doctor metadata is loaded only for included doctors','this.doctors.find({ where: { userId: In(doctorIds)' in service)
check('doctor name, specialty, clinic and approval state are returned',all(x in service for x in ['fullName: doctor.fullName','specialty: doctor.specialty','clinicName: doctor.clinicName','currentlyApproved: doctor.status === DoctorProfileStatus.APPROVED']))
check('shared record details are scoped to patient-owned non-deleted records',"this.records.find({ where: { id: In(recordIds), patientUserId: actor.sub, deletedAt: IsNull() }" in service)
check('deleted or missing records are omitted','filter((record): record is MedicalRecord => !!record)' in service)
check('attachment counts are included per shared record','attachmentCount: attachmentCount.get(record.id) || 0' in service)
check('consent expiry, download and revocation metadata remain present',all(x in service for x in ['expiresAt: true','allowDownload: true','revokedAt: true','createdAt: true']))
check('whole consent revocation is restricted to its owning patient',"where: { id, patientUserId: actor.sub }" in service)
check('per-record revoke remains transactional and row-locked',"this.dataSource.transaction(async manager =>" in service and "setLock('pessimistic_write')" in service)
check('per-record revoke only removes selected record','consent.recordIds = consent.recordIds.filter(id => id !== recordId)' in service)
check('empty consent is revoked after final record removal','if (consent.recordIds.length === 0) consent.revokedAt = new Date()' in service)
check('controller exposes list, whole-revoke and record-revoke endpoints',all(x in controller for x in ["@Get('share-consents')","@Delete('share-consents/:id')","@Delete('share-consents/:id/records/:recordId')"]))
check('mobile shows doctor name instead of raw user ID','item.doctor?.fullName' in screen and 'معرّف الطبيب:' not in screen)
check('mobile shows specialty and clinic',all(x in screen for x in ['item.doctor?.specialty','item.doctor?.clinicName']))
check('mobile shows shared record titles and attachment counts',all(x in screen for x in ['item.records','record.title','record.attachmentCount']))
check('mobile distinguishes active, expired and revoked states',all(x in screen for x in ["revoked?'ملغاة'","expired?'منتهية':'سارية'",'const expired=','const revoked=']))
check('mobile allows per-record revoke and full revoke only while active',all(x in screen for x in ['revokeSharedRecord(item.id,record.id,record.title)','!revoked&&!expired&&<Action title="سحب صلاحية الطبيب"']))
check('mobile refreshes share state after per-record revoke','await api.revokeMedicalSharedRecord(consentId,recordId);await loadShares();' in screen)
check('mobile API exposes both revocation operations',all(x in api for x in ['revokeMedicalShare:','revokeMedicalSharedRecord:']))
check('attachment download still requires active consent and download permission',"c.revokedAt IS NULL AND c.expiresAt > NOW()" in uploads and 'c.allowDownload = true' in uploads)
failed=[name for name,ok in checks if not ok]
for name,ok in checks: print(('PASS' if ok else 'FAIL')+' | '+name)
print(f'RESULT: {len(checks)-len(failed)}/{len(checks)}')
if failed: sys.exit(1)
